import{_ as r,C as n,o as t,c as s,a2 as i,b as d,w as a,a as l,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const C=JSON.parse('{"title":"NitroCord","description":"Minecraft proxy with built-in attack prevention — a Velocity fork by PingLess Studios","frontmatter":{"title":"NitroCord","description":"Minecraft proxy with built-in attack prevention — a Velocity fork by PingLess Studios","head":[["meta",{"name":"og:title","content":"NitroCord — Velocity fork with built-in attack prevention"}],["meta",{"name":"og:description","content":"Drop-in Velocity 4.1.0 replacement with a license-gated protection engine — kernel firewall, TCP fingerprinting, anti-bot verification, anti-VPN, GeoIP and packet flood scoring."}]]},"headers":[],"relativePath":"nitrocord/index.md","filePath":"nitrocord/index.md","lastUpdated":1785341162000}'),h={name:"nitrocord/index.md"};function g(u,e,f,m,k,b){const o=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=i('<h1 id="nitrocord" tabindex="-1">NitroCord <a class="header-anchor" href="#nitrocord" aria-label="Permalink to &quot;NitroCord&quot;">​</a></h1><p><strong>Velocity-compatible Minecraft proxy with built-in, license-gated attack prevention.</strong></p><h2 id="what-is-nitrocord" tabindex="-1">What is NitroCord? <a class="header-anchor" href="#what-is-nitrocord" aria-label="Permalink to &quot;What is NitroCord?&quot;">​</a></h2><p>NitroCord is a fork of <a href="https://papermc.io/software/velocity" target="_blank" rel="noreferrer">Velocity</a> 4.1.0 and a drop-in replacement for it: plugins compiled against the Velocity API keep working unchanged, and <code>velocity.toml</code> plus every upstream feature behaves exactly as before. On top of that, NitroCord ships a built-in protection engine that vanilla Velocity does not have — an accept-time kernel firewall, TCP fingerprinting, an attack-mode state machine, anti-bot verification, anti-VPN and GeoIP blocking, packet flood scoring, a null-ping-proof MOTD cache and exploit filters for Log4Shell and tab-completion abuse.</p><p>The engine is configured through two standalone TOML files created next to <code>velocity.toml</code> on first start: <code>nitrocord.toml</code> (branding, theme colors, every message, license key) and <code>protection.toml</code> (every protection knob). Protection is unlocked by a commercial license key from <a href="https://altis.host" target="_blank" rel="noreferrer">Altis</a> — and because NitroCord is a commercial product, the proxy refuses to start without a valid key (startup prints <code>License Found</code> → <code>License Key Verified</code> and finishes with the pink/white <code>Protection Enabled</code> banner listing every active protection).</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Drop-in Velocity Replacement</strong>: Fork of Velocity 4.1.0 with 100% plugin compatibility — no plugin recompiles, no API renames</li><li><strong>Kernel-Level Firewall</strong>: Hostile IPs are dropped via <code>ipset</code> + <code>iptables</code> before they reach the Minecraft protocol; degrades to in-memory denial without root</li><li><strong>Accept-Time Gate</strong>: The first Netty handler rejects firewalled addresses, cached anti-VPN positives and suspicious fingerprints before any decoding runs</li><li><strong>TCP Fingerprinting</strong>: Reads kernel <code>tcp_info</code> (MSS, TTL, window) to flag raw-socket bot stacks and proxy/VPS software during attacks</li><li><strong>Attack-Mode State Machine</strong>: Engages at 40 connections/s, disengages after 60 calm seconds; escalates checks and suppresses kick messages (silent TCP RST) under heavy load</li><li><strong>Graduated Violations</strong>: 19 violation reasons tracked per IP — repeated strikes escalate from a plain kick to a timed firewall ban</li><li><strong>Anti-Bot Verification</strong>: Ping-before-join reconnect check, accounts-per-IP limit, nickname blacklist, fastchat and shared-password detection, name-pattern and strange-name heuristics — with automatic Geyser/Floodgate exemption for Bedrock players</li><li><strong>Anti-VPN</strong>: 7 offline blocklists refreshed in the background, an optional online API chain (getipintel, proxycheck.io, IPHub), a persistent on-disk cache and a post-login recheck</li><li><strong>GeoIP Country Blocking</strong>: MaxMind GeoLite2 country lookups with automatic database updates</li><li><strong>Packet Flood Scoring</strong>: Anti-cheat-style violation levels per byte and per packet — cancel, then kick</li><li><strong>Null-Ping-Proof MOTD Cache</strong>: During attacks, server list pings are answered from a synthesized cache without firing <code>ProxyPingEvent</code> or contacting backend servers</li><li><strong>Exploit Filters</strong>: Log4Shell (<code>${...}</code> JNDI) filtering on chat, commands and client settings, plus a tab-completion expression filter</li></ul><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/getting-started/installation">Installation</a></li><li><a href="/pingless-studios-docs/nitrocord/getting-started/quick-start">Quick Start</a></li><li><a href="/pingless-studios-docs/nitrocord/configuration/reference">Configuration Reference</a></li><li><a href="/pingless-studios-docs/nitrocord/user-guide/cli">CLI Reference</a></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Every connection passes three ordered gates before it becomes a verified player:</p>',11)),(t(),d(p,null,{default:a(()=>[c(o,{id:"mermaid-111",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20C(%5BMinecraft%20client%5D)%20--%3E%20K%7B%22Kernel%20firewall%3Cbr%2F%3Eipset%20%2B%20iptables%22%7D%0A%20%20%20%20K%20--%3E%7C%22firewalled%22%7C%20X0%5B%22Packets%20dropped%3Cbr%2F%3Ebefore%20Netty%22%5D%0A%20%20%20%20K%20--%3E%7C%22pass%22%7C%20A%5B%22Accept-time%20gate%3Cbr%2F%3Efirewall%20%C2%B7%20cached%20anti-VPN%20%C2%B7%20TCP%20fingerprint%22%5D%0A%20%20%20%20A%20--%3E%7C%22deny%22%7C%20X1%5B%22Close%20%2F%20silent%20TCP%20RST%22%5D%0A%20%20%20%20A%20--%3E%7C%22pass%22%7C%20B%5B%22Handshake%20gate%3Cbr%2F%3Erate%20limit%20%C2%B7%20reconnect%20%C2%B7%20anti-VPN%20lists%20%C2%B7%20country%20%C2%B7%20DNS%22%5D%0A%20%20%20%20B%20--%3E%7C%22deny%22%7C%20X2%5B%22Kick%20%2F%20silent%20TCP%20RST%22%5D%0A%20%20%20%20B%20--%3E%7C%22pass%22%7C%20L%5B%22Login%20gate%3Cbr%2F%3ELog4Shell%20filter%20%C2%B7%20accounts%20%C2%B7%20nickname%20%C2%B7%20name%20heuristics%20%C2%B7%20online%20anti-VPN%22%5D%0A%20%20%20%20L%20--%3E%7C%22deny%22%7C%20X3%5B%22Kick%20%2F%20silent%20TCP%20RST%22%5D%0A%20%20%20%20L%20--%3E%7C%22pass%22%7C%20V%5B%22Verified%20player%3Cbr%2F%3Eremembered%20for%2030%20days%22%5D%0A%20%20%20%20V%20--%3E%20BE%5B%22Backend%20servers%22%5D%0A%0A%20%20%20%20subgraph%20AM%5B%22Attack-mode%20state%20machine%22%5D%0A%20%20%20%20%20%20%20%20AM1%5B%22Engages%20at%20%3E%3D%2040%20conn%2Fs%22%5D%20--%3E%20AM2%5B%22Disengages%20after%2060%20s%3Cbr%2F%3Ebelow%20threshold%22%5D%0A%20%20%20%20end%0A%20%20%20%20AM%20-.-%3E%7C%22escalates%20checks%2C%20suppresses%20kicks%20at%20%3E%3D%20150%20conn%2Fs%22%7C%20A%0A%20%20%20%20AM%20-.-%3E%20B%0A%20%20%20%20AM%20-.-%3E%20L%0A%0A%20%20%20%20VIO%5B%22Graduated%20violations%3Cbr%2F%3E19%20reasons%2C%20strikes%20escalate%20from%20kick%20to%20firewall%20ban%22%5D%0A%20%20%20%20A%20-.-%3E%20VIO%0A%20%20%20%20B%20-.-%3E%20VIO%0A%20%20%20%20L%20-.-%3E%20VIO%0A%20%20%20%20VIO%20--%3E%7C%22adds%20IP%20for%20ban-time-seconds%22%7C%20K%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<div class="info custom-block"><p class="custom-block-title">Verified-player fast path</p><p>Addresses that complete a full login are remembered for 30 days (<code>[whitelist]</code> in <code>protection.toml</code>) and skip the gates entirely — legitimate players never pay for protection twice.</p></div><h2 id="how-it-compares" tabindex="-1">How it compares <a class="header-anchor" href="#how-it-compares" aria-label="Permalink to &quot;How it compares&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>NitroCord</th><th>Vanilla Velocity</th><th>Waterfall-era forks (FlameCord / MangoCord)</th></tr></thead><tbody><tr><td>Plugin compatibility</td><td>Velocity 4.1.0 API, plugins unchanged</td><td>Velocity API (reference)</td><td>BungeeCord/Waterfall API</td></tr><tr><td>Kernel firewall</td><td>✅ ipset + iptables, in-memory fallback</td><td>❌</td><td>FlameCord only (iptables/ipset)</td></tr><tr><td>TCP fingerprinting</td><td>✅ kernel <code>tcp_info</code> (MSS/TTL/window)</td><td>❌</td><td>❌</td></tr><tr><td>Attack-mode adaptation</td><td>✅ state machine + kick suppression</td><td>❌</td><td>❌</td></tr><tr><td>Anti-bot checks</td><td>✅ reconnect, accounts, nickname, fastchat, password, name heuristics</td><td>❌</td><td>✅ similar check set</td></tr><tr><td>Anti-VPN</td><td>✅ 7 blocklists + online APIs + persistent cache</td><td>❌</td><td>✅ blocklists</td></tr><tr><td>GeoIP</td><td>✅ GeoLite2, auto-update</td><td>❌</td><td>✅ GeoLite2</td></tr><tr><td>Packet limits</td><td>✅ per-byte/per-packet violation scoring</td><td>Frame length caps only</td><td>✅ vls-style scoring</td></tr><tr><td>MOTD flood protection</td><td>✅ null-ping-proof cache, no backend contact</td><td>❌</td><td>Partial (ping rate limit)</td></tr><tr><td>Maintained upstream</td><td>✅ tracks Velocity 4.1.0 (active)</td><td>✅ PaperMC</td><td>❌ Waterfall EOL March 2024</td></tr><tr><td>License</td><td>Commercial key (Altis), required to run</td><td>GPLv3, free</td><td>FlameCord paid; MangoCord free (MIT), unmaintained since 2023</td></tr></tbody></table><p>NitroCord keeps the Velocity ecosystem you already run and adds the protection layer Waterfall-era forks pioneered — on a maintained upstream, with TCP fingerprinting and attack-mode adaptation they never had.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Java 25</strong> — NitroCord is built for and runs on the Java 25 toolchain</li><li><strong>Linux</strong> — the kernel firewall additionally needs <strong>root</strong> plus <code>ipset</code> and <code>iptables</code>; without them it degrades to in-memory denial with a warning</li><li><strong>NitroCord license key</strong> — issued by the Altis dashboard after purchase, entered as <code>license-key</code> in <code>nitrocord.toml</code>; required to enable attack prevention</li><li><strong>MaxMind license key</strong> — optional, only needed for GeoIP country blocking (free at <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noreferrer">maxmind.com</a>)</li></ul>',6))])}const P=r(h,[["render",g]]);export{C as __pageData,P as default};
